import { tags } from "typia";

/**
 * Blocking validation error for a cart or cart item.
 *
 * Represents a condition that must be resolved before checkout can proceed,
 * such as an inactive SKU, insufficient inventory, or an invalid price. Errors
 * may apply to the cart as a whole or to a particular cart item.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallCartValidationError = {
  /**
   * Machine-readable error code identifying the specific validation rule that
   * failed.
   *
   * Codes are stable identifiers used by clients to implement rule-specific
   * handling or localization, for example: CART_SKU_INACTIVE,
   * CART_INSUFFICIENT_STOCK, CART_PRICE_MISMATCH.
   */
  code: string;

  /**
   * Human-readable explanation of the validation error.
   *
   * Intended to be displayed to end users or support staff. May be localized
   * by the client based on the code if desired.
   */
  message: string;

  /**
   * Identifier of the affected cart item in the shopping_mall_cart_items
   * table, when the error is item-specific.
   *
   * If the error applies to the cart as a whole (for example, cart is empty),
   * this field may be omitted or set to null using a different DTO variant if
   * needed.
   */
  cartItemId?: (string & tags.Format<"uuid">) | undefined;
};
